mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM game_completion
    WHERE game_id = #{gameId}
)

SELECT total_games, wins, losses, rating AS experience
FROM user_stats
WHERE user_id = #{userId}

SELECT EXISTS (
    SELECT 1
    FROM `user`
    WHERE email = #{email}
)

SELECT EXISTS (
    SELECT 1
    FROM `user`
    WHERE user_name = #{nickname}
)
